INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('d2fb428d373f3f55', 'brand_bonk_golf', '32ee6e8ba9ecb17c', 1, 1, 1, 'live', 'You don''t need another hat', 'Most golf hats just sit there. This one holds your marker and your tees, so you stop digging in your pockets.', 'The golfer who already owns ten hats', 'Any snapback', 'Talk to camera, then use it', '["You don''t need another golf hat.", "Watch this before you buy your next hat.", "I have ten hats. I wear one."]', '[{"label": "Open · 0 to 3s", "text": "Old hat off, Bonk on. Say the line."}, {"label": "Middle", "text": "On the green: marker off the bill, mark, ball up, marker back on."}, {"label": "Close", "text": "Tee out of the side slot on the next tee. \"That is the whole point.\""}]', 'Toss an old faded hat out of frame, put the Bonk on in the same second.', 'At 4 seconds, pull the marker off the bill and drop it behind the ball in one move.', '[]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, note, section_id, shown, sort, board_sort) SELECT '5ea5cca3e4a3bb37', 'brand_bonk_golf', 'd2fb428d373f3f55', 'meta', '52555959742213', 'You don''t need another hat. You need one that does something.', '32ee6e8ba9ecb17c', 1, 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_12528825' AND ad_id='52555959742213');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('8b5c95a43910e447', 'brand_bonk_golf', '32ee6e8ba9ecb17c', 0, 0, 2, 'live', 'Name the design, show the magnet', 'A close, friendly look at one hat: the design up close, then the marker on the magnet.', 'Anyone with a Bonk hat they love', 'One hat, by name', 'Selfie close-up', '["Somebody order a Breakfast Ball?", "This is the cleanest hat I own.", "Look at the stitching on this."]', '[{"label": "Open · 0 to 3s", "text": "Selfie, tap the logo, say its name."}, {"label": "Middle", "text": "Turn your head: side tee slots, then the marker on the bill."}, {"label": "Close", "text": "Marker off, marker back on. \"Link is below.\""}]', 'Phone at arm length, tap the logo with one finger in the first second.', 'Flip the hat over and show the inside, then the bill with the marker on it.', '[{"brand": "Pins & Aces", "what": "Hat on, hand on the brim, show the marker on the magnet. Name the hat and stop.", "url": null}]');
