INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('db933022963ef6ca', 'brand_bonk_golf', 'b6d7704960fffbbc', 1, 2, 3, 'live', 'Off the couch, onto the course', 'A gift that gets him golfing, so everyone wins. Told by the wife, with a smile.', 'Wives and girlfriends buying for him', 'Any snapback, or the set', 'Wife voiceover', '["I love my husband, but I need the house to myself.", "Best gift I bought him this year.", "He has not been on the couch since."]', '[{"label": "Open · 0 to 3s", "text": "Couch, remote, hat lands on his chest."}, {"label": "Middle", "text": "Him trying it on, finding the marker. \"Wait, what is this?\""}, {"label": "Close", "text": "Out the door with clubs. \"Mutually beneficial.\""}]', 'Him asleep on the couch with the remote. She drops the hat on his chest.', 'Cut to him walking out the door with clubs, hat on. She waves.', '[]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, note, section_id, shown, sort, board_sort) SELECT 'e2215d50c50c0ab6', 'brand_bonk_golf', 'db933022963ef6ca', 'meta', '52555960295213', '"Sponsor his new hobby." She opens the box, he tries it on in front of his hat wall.', 'b6d7704960fffbbc', 1, 1, 3 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_12528825' AND ad_id='52555960295213');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('0afdca3d492bd365', 'brand_bonk_golf', 'b6d7704960fffbbc', 0, 0, 4, 'live', 'My husband finally tried it', 'She bought it, he loves it. The gift-giver proving it was a good buy.', 'Wives buying for their golfer', 'Any hat, in the box', 'Hands-only unboxing, her voice', '["I have been trying to get my husband to try this hat for months.", "He finally wore it. Here is why.", "Best thing I got him this year."]', '[{"label": "Open · 0 to 3s", "text": "Box on the counter, hat comes out."}, {"label": "Middle", "text": "Marker off the bill, tee into the side slot."}, {"label": "Close", "text": "\"If he golfs, get him one.\""}]', 'Box on the counter, hat lifted out in the first second.', 'Pull the marker off the bill on camera: "this is the part he loves."', '[{"brand": "Melin", "what": "Unbox it on the counter, then tell us why he will not take it off.", "url": null}]');
